const body = $input.first().json.body || $input.first().json;

// Evolution API v2 envia eventos com estrutura:
// { event: 'messages.upsert', data: { key: {...}, message: {...}, ... } }
const event = body.event;
const data = body.data || body;

// Ignorar eventos que não são mensagens
if (event && event !== 'messages.upsert') {
  return [];
}

// Extrair mensagem
const message = data.message;
if (!message) return [];

// Texto da mensagem (pode vir de conversation ou extendedTextMessage)
const text = message.conversation 
  || message.extendedTextMessage?.text 
  || '';

if (!text || !text.trim()) return [];

// Info do remetente
const remoteJid = data.key?.remoteJid || '';
const fromMe = data.key?.fromMe || false;
const participant = data.key?.participant || remoteJid;
const pushName = data.pushName || 'Desconhecido';
const isGroup = remoteJid.endsWith('@g.us');

// Detectar comando (case insensitive, trim)
const cleanText = text.trim().toLowerCase();

let command = 'none';
let args = '';

if (cleanText.startsWith('status projeto')) {
  command = 'status_projeto';
  args = text.trim().substring('status projeto'.length).trim();
} else if (cleanText === 'tarefas pendentes') {
  command = 'tarefas_pendentes';
} else if (cleanText === 'briefing da semana') {
  command = 'briefing_semana';
} else if (cleanText === 'resumo diario' || cleanText === 'resumo diário') {
  command = 'resumo_diario';
} else if (cleanText === 'ajuda' || cleanText === 'help') {
  command = 'ajuda';
}

return [{
  json: {
    command,
    args,
    originalText: text.trim(),
    remoteJid,
    participant,
    pushName,
    isGroup,
    fromMe
  }
}];

const input = $('Parse Message').first().json;
const response = $input.first().json;
const tasks = response.tasks || [];

if (tasks.length === 0) {
  return [{ json: { message: '✅ Nenhuma tarefa pendente! Tudo em dia.', replyTo: input.remoteJid } }];
}

let msg = `📋 *Tarefas Pendentes* (${tasks.length})\n\n`;

const grouped = {};
for (const t of tasks) {
  const list = t.list?.name || 'Outros';
  if (!grouped[list]) grouped[list] = [];
  grouped[list].push(t);
}

for (const [list, listTasks] of Object.entries(grouped)) {
  msg += `*${list}:*\n`;
  for (const t of listTasks.slice(0, 5)) {
    const status = t.status?.status || '?';
    const assignee = (t.assignees || []).map(a => a.username).join(', ') || '-';
    const due = t.due_date ? new Date(parseInt(t.due_date)).toLocaleDateString('pt-BR') : 'S/D';
    const overdue = t.due_date && parseInt(t.due_date) < Date.now() ? ' ⚠️' : '';
    msg += `  • ${t.name} [${status}] 👤${assignee} 📅${due}${overdue}\n`;
  }
  if (listTasks.length > 5) msg += `  _... +${listTasks.length - 5} tasks_\n`;
  msg += '\n';
}

return [{ json: { message: msg.trim(), replyTo: input.remoteJid } }];

const input = $('Parse Message').first().json;
const projectName = input.args.toLowerCase();
const response = $input.first().json;
const tasks = (response.tasks || []).filter(t => {
  const name = (t.name || '').toLowerCase();
  const tags = (t.tags || []).map(tag => tag.name.toLowerCase());
  const list = (t.list?.name || '').toLowerCase();
  return name.includes(projectName) || tags.includes(projectName) || list.includes(projectName);
});

if (tasks.length === 0) {
  return [{ json: { message: `🔍 Nenhuma task encontrada para "${input.args}".`, replyTo: input.remoteJid } }];
}

let msg = `📊 *Status: ${input.args}* (${tasks.length} tasks)\n\n`;
for (const t of tasks.slice(0, 10)) {
  const status = t.status?.status || '?';
  const emoji = status.toLowerCase().includes('complete') || status.toLowerCase().includes('conclu') ? '✅' : status.toLowerCase().includes('progress') || status.toLowerCase().includes('andamento') ? '🔄' : '📋';
  const assignee = (t.assignees || []).map(a => a.username).join(', ') || '-';
  msg += `${emoji} *${t.name}*\n   ${status} | 👤 ${assignee}\n`;
}
if (tasks.length > 10) msg += `\n_... +${tasks.length - 10} tasks_`;

return [{ json: { message: msg.trim(), replyTo: input.remoteJid } }];

